export function mergeHarnessLocale<T extends Record<string, unknown>>(
  localeKey: LocaleKey,
  messages: T
): T {
  const harnessPatch = mergeLocaleNodes(
    mergeLocaleNodes(
      mergeLocaleNodes(
        baseHarnessPatch as LocaleNode,
        (localeHarnessOverrides[localeKey] ?? {}) as LocaleNode
      ),
      (legacyHarnessPatches[localeKey] ?? {}) as LocaleNode
    ),
    (harnessGroupBackfills[localeKey] ?? {}) as LocaleNode
  )
  const structuralPatch = mergeLocaleNodes(
    mergeLocaleNodes(
      mergeLocaleNodes(
        mergeLocaleNodes(
          (systemDashboardCardOverrides[localeKey] ?? {}) as LocaleNode,
          (dashboardCardCopyOverrides[localeKey] ?? {}) as LocaleNode
        ),
        (localeStructuralBackfills[localeKey] ?? {}) as LocaleNode
      ),
      (extensionsBrowseBackfills[localeKey] ?? {}) as LocaleNode
    ),
    (localeFollowupBackfills[localeKey] ?? {}) as LocaleNode
  )
  const mergedMessages = mergeLocaleNodes(structuralPatch, messages as unknown as LocaleNode)
  const skillStorePatch = buildSkillStoreDerivedBackfill(
    localeKey,
    mergedMessages as unknown as Record<string, unknown>
  ) as LocaleNode
  const mergedWithSkillStore = mergeLocaleNodes(mergedMessages, skillStorePatch)
  const postMergePatch = buildLocalePostMergeBackfill(
    localeKey,
    mergedWithSkillStore as unknown as Record<string, unknown>
  ) as LocaleNode
  const mergedWithPostMerge = mergeLocaleNodes(mergedWithSkillStore, postMergePatch)
  const settingsPatch = mergeLocaleNodes(
    agentcoreRunnerSettingsBase,
    (agentcoreRunnerSettingsOverrides[localeKey] ?? {}) as LocaleNode
  )
  const currentHarness = (mergedWithPostMerge.harness ?? {}) as LocaleNode
  const currentSettings = (mergedWithPostMerge.settings ?? {}) as LocaleNode

  return {
    ...(mergedWithPostMerge as T),
    settings: mergeLocaleNodes(currentSettings, {
      agentcoreRunner: settingsPatch,
    } as LocaleNode),
    harness: mergeLocaleNodes(currentHarness, harnessPatch),
  } as T
}
